L06_C4_B1_09.latex:
\begin{ex}%[6H4N1]
\immini[thm]{
Tính diện tích hình sau biết ${GH}=4cm$, ${FH}=10cm$, ${GE}=9cm$, ${FE}=5cm$ 

\choice
{ $170cm^{2}$  }
   {  $85cm^{2}$ }
     { \True  $\dfrac{85}{2}cm^{2}$ }
    {  $\dfrac{85}{4}cm^{2}$ }
}{
\begin{tikzpicture}
    % Định nghĩa tọa độ của các điểm A và C (đường kính)
    \coordinate (A) at (0,0);
    \coordinate (C) at (6,0);
    \coordinate (B) at (1,2.236);  % Điểm B nằm trên đường tròn
    \coordinate (D) at (4,-2.828); % Điểm D nằm trên đường tròn

    \draw[blue, thick] (A) -- (B) -- (C) -- (D) -- cycle;

    \def\khvuong[size=#1](#2,#3,#4){%
        \draw ($(#3)!#1!(#2)$) --
        ($($(#3)!#1!(#2)$)+($(#3)!#1!(#4)$)-(#3)$)--
        ($(#3)!#1!(#4)$);
    }
    \khvuong[size=7pt](C,B,A);
        \khvuong[size=7pt](C,D,A);
    \filldraw[black] (A) circle (2pt) node[below left] {$G$};
    \filldraw[black] (B) circle (2pt) node[above left] {$H$};
    \filldraw[black] (C) circle (2pt) node[below right] {$F$};
    \filldraw[black] (D) circle (2pt) node[below right] {$E$};
\end{tikzpicture}
}
\loigiai{
Diện tích tam giác ${GHF}$ bằng $\dfrac{1}{2}GH.HF=\dfrac{1}{2}4.10=20cm^{2}$\\
Diện tích tam giác ${GEF}$ bằng $\dfrac{1}{2}GE.EF=\dfrac{1}{2}9.5=\dfrac{45}{2}cm^{2}$\\
Diện tích của hình là $20cm^{2}+ \dfrac{45}{2}cm^{2}=\dfrac{85}{2}cm^{2}$
}\end{ex}

